function nav($path,$label){$active=basename($_SERVER['PHP_SELF'])===$path?'active':''; echo '<a class="'.$active.'" href="/'.$path.'">'.$label.'</a>';}
function page_start($title){global $appName,$flash,$dbError;?><!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?> - <?=h($appName)?></title><link rel="stylesheet" href="/style.css"></head><body><aside><div class="brand">📦 Stock Management</div><?php nav('dashboard.php','แดชบอร์ด'); nav('products.php','คลังสินค้า'); nav('stock_in.php','สินค้าเข้า'); nav('stock_out.php','สินค้าออก'); nav('movements.php','รายการเคลื่อนไหวล่าสุด'); nav('reports.php','รายงานสรุป'); nav('password.php','เปลี่ยนรหัสผ่าน'); if(is_admin()) nav('users.php','การจัดการผู้ใช้งาน');?><a href="/logout.php">ออกจากระบบ</a></aside><main><header><div><h2><?=h($title)?></h2><div class="muted">ระบบจัดการสต๊อกสินค้า</div></div><div class="user-pill">👤 <?=h($_SESSION['user']['full_name'])?> · <?=h($_SESSION['user']['role'])?></div></header><?php if(!empty($dbError)):?><div class="alert danger">Database Error: <?=h($dbError)?></div><?php endif;?><?php if($flash):?><div class="alert <?=h($flash[0])?>"><?=h($flash[1])?></div><?php endif;?><?php }
